using System.Collections.Generic;
using OurWorld.Core;
using UnityEngine;
using UnityEngine.UI;

namespace OurWorld.UI
{
    /// <summary>
    /// Mounts the Blender-rendered HUD icons (Resources/UI/Icons, generated by
    /// scripts/blender/generate_ui_icons.py) onto the existing HUD buttons at runtime,
    /// so the scene / UI builder does not have to be regenerated.
    /// Round and pedal buttons get a large centred icon with a small caption underneath;
    /// wide buttons get a leading icon with the caption shifted right.
    /// </summary>
    public class HudIconSkin : MonoBehaviour
    {
        private enum Layout
        {
            Stacked,    // icon on top, small caption below (round / pedal buttons)
            IconOnly,   // replace caption (steering arrows)
            Leading     // icon left of the caption (wide buttons)
        }

        private struct Entry
        {
            public string button;
            public string icon;
            public Layout layout;
            public string captionKey;   // optional: replaces static captions such as "▲\nGAZ"
            public string captionFallback;

            public Entry(string button, string icon, Layout layout, string captionKey = null, string captionFallback = null)
            {
                this.button = button;
                this.icon = icon;
                this.layout = layout;
                this.captionKey = captionKey;
                this.captionFallback = captionFallback;
            }
        }

        private static readonly Entry[] Entries =
        {
            new Entry("Btn_Jump", "icon_jump", Layout.Stacked, "ui.btn.jump", "Atla"),
            new Entry("Btn_Attack", "icon_attack", Layout.Stacked, "ui.btn.attack", "Vur"),
            new Entry("Btn_Sprint", "icon_sprint", Layout.Stacked),
            new Entry("Btn_Gas", "icon_gas", Layout.Stacked, "ui.btn.gas", "GAZ"),
            new Entry("Btn_Brake", "icon_brake", Layout.Stacked, "ui.btn.brake", "FREN"),
            new Entry("Btn_SteerLeft", "icon_steer_left", Layout.IconOnly),
            new Entry("Btn_SteerRight", "icon_steer_right", Layout.IconOnly),
            new Entry("Btn_Handbrake", "icon_handbrake", Layout.Leading),
            new Entry("Btn_ExitCar", "icon_exit_car", Layout.Leading),
            new Entry("Btn_Interact", "icon_interact", Layout.Leading),
            new Entry("Btn_Phone", "icon_phone", Layout.Leading),
        };

        private static readonly Dictionary<string, Sprite> SpriteCache = new Dictionary<string, Sprite>();
        private readonly List<(Text label, string key, string fallback)> _captions = new List<(Text, string, string)>();

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
        private static void Bootstrap()
        {
            if (FindAnyObjectByType<HudIconSkin>() != null) return;
            if (FindAnyObjectByType<GameHUDController>() == null) return;
            new GameObject("HudIconSkin").AddComponent<HudIconSkin>();
        }

        private void Start()
        {
            Dictionary<string, RectTransform> byName = new Dictionary<string, RectTransform>();
            foreach (RectTransform rt in FindObjectsByType<RectTransform>(FindObjectsInactive.Include))
            {
                if (rt != null && rt.name.StartsWith("Btn_") && !byName.ContainsKey(rt.name))
                {
                    byName[rt.name] = rt;
                }
            }

            foreach (Entry e in Entries)
            {
                if (!byName.TryGetValue(e.button, out RectTransform btn)) continue;
                Sprite sprite = LoadIcon(e.icon);
                if (sprite == null) continue;
                Apply(btn, sprite, e);
            }

            if (LocalizationService.Instance != null)
            {
                LocalizationService.Instance.OnLanguageChanged += HandleLanguageChanged;
            }
            RefreshCaptions();
        }

        private void OnDestroy()
        {
            if (LocalizationService.Instance != null)
            {
                LocalizationService.Instance.OnLanguageChanged -= HandleLanguageChanged;
            }
        }

        private void HandleLanguageChanged(string _)
        {
            RefreshCaptions();
        }

        private void RefreshCaptions()
        {
            foreach ((Text label, string key, string fallback) in _captions)
            {
                if (label != null) label.text = LocalizationService.Tr(key, fallback);
            }
        }

        private void Apply(RectTransform btn, Sprite sprite, Entry e)
        {
            if (btn.Find("HudIcon") != null) return; // already skinned

            Text label = btn.GetComponentInChildren<Text>(true);
            Color tint = label != null ? label.color : new Color(0.93f, 0.94f, 0.95f, 1f);
            tint.a = 1f;

            GameObject iconGo = new GameObject("HudIcon", typeof(RectTransform), typeof(Image));
            iconGo.transform.SetParent(btn, false);
            RectTransform irt = (RectTransform)iconGo.transform;
            Image img = iconGo.GetComponent<Image>();
            img.sprite = sprite;
            img.preserveAspect = true;
            img.raycastTarget = false;
            img.color = tint;
            Shadow sh = iconGo.AddComponent<Shadow>();
            sh.effectColor = new Color(0f, 0f, 0f, 0.35f);
            sh.effectDistance = new Vector2(1.5f, -2f);

            Vector2 size = btn.rect.size;
            switch (e.layout)
            {
                case Layout.Stacked:
                {
                    irt.anchorMin = new Vector2(0.18f, 0.34f);
                    irt.anchorMax = new Vector2(0.82f, 0.90f);
                    irt.offsetMin = irt.offsetMax = Vector2.zero;
                    if (label != null)
                    {
                        RectTransform lrt = label.rectTransform;
                        lrt.anchorMin = new Vector2(0.05f, 0.06f);
                        lrt.anchorMax = new Vector2(0.95f, 0.36f);
                        lrt.offsetMin = lrt.offsetMax = Vector2.zero;
                        label.alignment = TextAnchor.MiddleCenter;
                        label.resizeTextForBestFit = true;
                        label.resizeTextMinSize = 15;
                        label.resizeTextMaxSize = Mathf.Max(18, Mathf.RoundToInt(label.fontSize * 0.85f));
                        if (!string.IsNullOrEmpty(e.captionKey))
                        {
                            _captions.Add((label, e.captionKey, e.captionFallback));
                        }
                    }
                    break;
                }
                case Layout.IconOnly:
                {
                    irt.anchorMin = new Vector2(0.22f, 0.20f);
                    irt.anchorMax = new Vector2(0.78f, 0.80f);
                    irt.offsetMin = irt.offsetMax = Vector2.zero;
                    if (label != null) label.enabled = false;
                    break;
                }
                case Layout.Leading:
                {
                    float iconSize = Mathf.Min(size.y * 0.58f, 52f);
                    float pad = Mathf.Max(10f, size.y * 0.18f);
                    irt.anchorMin = new Vector2(0f, 0.5f);
                    irt.anchorMax = new Vector2(0f, 0.5f);
                    irt.pivot = new Vector2(0f, 0.5f);
                    irt.anchoredPosition = new Vector2(pad, 0f);
                    irt.sizeDelta = new Vector2(iconSize, iconSize);
                    if (label != null)
                    {
                        RectTransform lrt = label.rectTransform;
                        lrt.offsetMin = new Vector2(lrt.offsetMin.x + pad + iconSize * 0.85f, lrt.offsetMin.y);
                        label.resizeTextForBestFit = true;
                        label.resizeTextMinSize = 16;
                        label.resizeTextMaxSize = Mathf.Max(22, label.fontSize);
                    }
                    break;
                }
            }
        }

        private static Sprite LoadIcon(string name)
        {
            if (SpriteCache.TryGetValue(name, out Sprite cached)) return cached;

            string path = $"UI/Icons/{name}";
            Sprite sprite = Resources.Load<Sprite>(path);
            if (sprite == null)
            {
                Texture2D tex = Resources.Load<Texture2D>(path);
                if (tex != null)
                {
                    sprite = Sprite.Create(tex, new Rect(0, 0, tex.width, tex.height), new Vector2(0.5f, 0.5f), 100f);
                    sprite.name = name;
                }
            }

            SpriteCache[name] = sprite;
            return sprite;
        }
    }
}
